using Microsoft.EntityFrameworkCore;
using Purview.ValueObjects.Serialization;

namespace Purview.ValueObjects.EFCompatibility;

/// <summary>
/// A scalar value object whose key value is generated by Entity Framework Core, so this type also proves
/// the generated key value generator, the identifier helper, and the key generator convention work on every
/// supported Entity Framework Core version.
/// </summary>
[Scalar(GenerateEFValueGenerator = true)]
public readonly partial record struct CompatibilityId
{
	/// <summary>Gets the identifier value.</summary>
	public Guid Value { get; }

	static partial void OnValidate(Guid value)
	{
		if (value == Guid.Empty)
			throw new ArgumentException("Identifier cannot be empty.", nameof(value));
	}
}

/// <summary>A scalar value object persisted in its own column through a generated value converter.</summary>
[Scalar]
public readonly partial record struct CompatibilityCode
{
	/// <summary>Gets the code value.</summary>
	public string Value { get; }

	static partial void OnValidate(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
			throw new ArgumentException("Code cannot be empty.", nameof(value));
	}
}

/// <summary>
/// A nullable value-type scalar using the automatic form. Its provider type is <c>int?</c>, so the generated
/// Entity Framework Core converter has to accept and produce null on both directions.
/// </summary>
[Scalar<int?>]
public readonly partial record struct CompatibilityScore { }

/// <summary>A nullable string scalar: null is a valid domain value and it round-trips JSON <c>null</c>.</summary>
[Scalar<string>(Nullable = true)]
public readonly partial record struct CompatibilityNickname { }

/// <summary>
/// The non-nullable counterpart of <see cref="CompatibilityNickname"/>. Mapping an entity property as
/// <c>CompatibilityName?</c> gives a nullable column whose <c>NULL</c> means "absent", while the DTO
/// keeps the nullable scalar and its <c>Null()</c> value.
/// </summary>
[Scalar<string>(Trim = true)]
public readonly partial record struct CompatibilityName { }

/// <summary>A nullable timestamp scalar, exercising the nullable value-type provider type.</summary>
[Scalar<DateTimeOffset>(Nullable = true)]
public readonly partial record struct CompatibilityObservedAt { }

/// <summary>The non-nullable counterpart of <see cref="CompatibilityObservedAt"/>.</summary>
[Scalar<DateTimeOffset>]
public readonly partial record struct CompatibilityRecordedAt { }

/// <summary>A nullable integer scalar.</summary>
[Scalar<int?>]
public readonly partial record struct CompatibilityQuantity { }

/// <summary>The non-nullable counterpart of <see cref="CompatibilityQuantity"/>.</summary>
[Scalar<int>]
public readonly partial record struct CompatibilityCount { }

/// <summary>
/// A complex value object mapped to a JSON column. This mapping is a value converter, so it works on every
/// Entity Framework Core version the package supports.
/// </summary>
[ValueObject(EFMapping = EntityFrameworkMapping.Json)]
public readonly partial record struct CompatibilityStamp
{
	/// <summary>Gets the recorded time.</summary>
	public DateTimeOffset RecordedAt { get; }

	/// <summary>Gets the origin of the stamp.</summary>
	public string Origin { get; }
}

/// <summary>
/// A complex value object mapped as an Entity Framework Core complex type, which needs EF Core 8 or later.
/// Against EF Core 7 the generator reports VO1019 and leaves the mapping out.
/// </summary>
[ValueObject]
public readonly partial record struct CompatibilityMoney
{
	/// <summary>Gets the amount.</summary>
	public decimal Amount { get; }

	/// <summary>Gets the currency of the amount.</summary>
	public CompatibilityCode Currency { get; }
}

/// <summary>
/// An entity that uses every value object mapping this project declares, so one model exercises the
/// converters, the JSON column, and - from EF Core 8 - the complex type.
/// </summary>
sealed class CompatibilityEntity
{
	/// <summary>Gets or sets the generated key.</summary>
	public CompatibilityId Id { get; set; }

	/// <summary>Gets or sets the code column.</summary>
	public CompatibilityCode Code { get; set; }

	/// <summary>Gets or sets the nullable value-type scalar column.</summary>
	public CompatibilityScore? Score { get; set; }

	/// <summary>Gets or sets the direct nullable-scalar shape: a <c>T?</c> property.</summary>
	public CompatibilityNickname? Nickname { get; set; }

	/// <summary>
	/// Gets or sets a nullable scalar on a non-nullable property. Entity Framework Core cannot mark a
	/// non-nullable struct property optional, so this stays a required column; <c>VO1031</c> reports it,
	/// which this deliberately exercises.
	/// </summary>
#pragma warning disable VO1031
	public CompatibilityNickname RequiredNickname { get; set; }
#pragma warning restore VO1031

	/// <summary>Gets or sets the two-scalar shape: a non-nullable scalar behind a nullable property.</summary>
	public CompatibilityName? PreferredName { get; set; }

	/// <summary>Gets or sets a nullable timestamp scalar through a nullable property.</summary>
	public CompatibilityObservedAt? ObservedAt { get; set; }

	/// <summary>Gets or sets a required timestamp scalar.</summary>
	public CompatibilityRecordedAt RecordedAt { get; set; }

	/// <summary>Gets or sets a nullable integer scalar through a nullable property.</summary>
	public CompatibilityQuantity? OptionalQuantity { get; set; }

	/// <summary>Gets or sets a required integer scalar.</summary>
	public CompatibilityCount Count { get; set; }

	/// <summary>
	/// Gets or sets a nullable scalar whose optionality is configured explicitly. The generated registry
	/// must leave that explicit configuration alone.
	/// </summary>
	public CompatibilityNickname? MandatoryNickname { get; set; }

	/// <summary>Gets or sets the JSON column.</summary>
	public CompatibilityStamp Stamp { get; set; }

#if !NET8_0
	/// <summary>Gets or sets the complex type mapped to columns, which needs EF Core 8 or later.</summary>
	public CompatibilityMoney Total { get; set; }
#endif
}

/// <summary>
/// A base type that declares a scalar value object column while not being an entity type itself. Entities that
/// derive from it inherit the property, so the generated registry has to map it through the entity type that
/// owns the row rather than through the property's declaring type.
/// </summary>
abstract class CompatibilityAuditedEntity
{
	/// <summary>Gets or sets the code of the last change applied to the row.</summary>
	public CompatibilityCode LastChangeCode { get; set; }
}

/// <summary>An entity whose mapped value object column is inherited from a base type that is not in the model.</summary>
sealed class CompatibilityInheritedEntity : CompatibilityAuditedEntity
{
	/// <summary>Gets or sets the generated key.</summary>
	public CompatibilityId Id { get; set; }
}

/// <summary>
/// The context under test. It maps the value objects through the generated registry and registers the
/// generated key value generator convention, exactly as an application would.
/// </summary>
sealed class CompatibilityDbContext(DbContextOptions<CompatibilityDbContext> options) : DbContext(options)
{
	/// <summary>Gets the entity set.</summary>
	public DbSet<CompatibilityEntity> Entities => Set<CompatibilityEntity>();

	/// <summary>Gets the entity set whose value object column is inherited.</summary>
	public DbSet<CompatibilityInheritedEntity> InheritedEntities => Set<CompatibilityInheritedEntity>();

	protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
	{
		base.ConfigureConventions(configurationBuilder);

		configurationBuilder.UseValueObjectKeyGenerators();
	}

	protected override void OnModelCreating(ModelBuilder modelBuilder)
	{
		// Configured before the registry, so the explicit requirement is the one that must survive.
		modelBuilder.Entity<CompatibilityEntity>().Property(entity => entity.MandatoryNickname).IsRequired();

		modelBuilder.ConfigureValueObjects();
	}
}
